+/* =========================
+   全体
+========================= */
+
+* {
+    box-sizing: border-box;
+}
+
+body {
+    margin: 0;
+    background-color: #f5f6f8;
+    color: #222;
+    font-family:
+        -apple-system,
+        BlinkMacSystemFont,
+        "Segoe UI",
+        "Noto Sans JP",
+        sans-serif;
+    line-height: 1.6;
+}
+
+
+/* =========================
+   ヘッダー
+========================= */
+
+header {
+    background-color: #ffffff;
+    border-bottom: 1px solid #e5e7eb;
+    padding: 16px 24px;
+}
+
+header h1 {
+    margin: 0;
+    font-size: 1.4rem;
+    font-weight: 700;
+}
+
+
+/* =========================
+   メインコンテンツ
+========================= */
+
+main {
+    width: min(100% - 32px, 1000px);
+    margin: 40px auto;
+}
+
+section {
+    background-color: #ffffff;
+    border: 1px solid #e5e7eb;
+    border-radius: 12px;
+    padding: 24px;
+    margin-bottom: 24px;
+}
+
+section h2 {
+    margin-top: 0;
+}
+
+
+/* =========================
+   フッター
+========================= */
+
+footer {
+    padding: 32px 24px;
+    text-align: center;
+    color: #666;
+    font-size: 0.9rem;
 }
